async function main(ctx) {
  const raw = String((ctx.input || {}).url || '').trim();
  if (!raw) throw new Error('url is required');

  if (typeof URL === 'function') {
    let u;
    try { u = new URL(raw); } catch (_) {
      throw new Error('url must be a valid absolute http(s) URL');
    }
    if (u.protocol !== 'http:' && u.protocol !== 'https:') {
      throw new Error('url must start with http:// or https://');
    }
    return { url: u.toString() };
  }

  if (!/^https?:\/\//i.test(raw)) throw new Error('url must start with http:// or https://');
  return { url: raw };
}

async function main(ctx) {
  const resp = ctx.input || {};
  const status = Number(resp.status ?? 0);

  if (Number.isFinite(status) && status >= 400) {
    const statusText = String(resp.statusText ?? '').trim();
    let bodyText = '';
    try {
      bodyText = typeof resp.body === 'string' ? resp.body : JSON.stringify(resp.body);
    } catch (_) {
      bodyText = String(resp.body ?? '');
    }

    if (status === 401 || status === 403) {
      throw new Error(
        `system.webFetch unauthorized (${status}${statusText ? ' ' + statusText : ''}). ` +
          `Platform secrets for the system connector may be missing. Body: ${bodyText}`
      );
    }

    throw new Error(
      `system.webFetch failed: ${status}${statusText ? ' ' + statusText : ''} | body: ${bodyText}`
    );
  }

  return resp;
}

async function main(ctx) {
  const resp = ctx.input || {};
  const body = resp.body;

  if (typeof body === 'string') return body;
  if (body == null) return '';

  // If backend returns non-string, still return markdown.
  try {
    return `~~~json\n${JSON.stringify(body, null, 2)}\n~~~`;
  } catch (_) {
    return String(body);
  }
}
